def find_objs(g):
 res=[]
 for r in range(len(g)-4):
  for c in range(len(g[0])-4):
   b=g[r][c]
   if all(g[r][c+j]==b and g[r+4][c+j]==b for j in range(5)) and all(g[r+i][c]==b and g[r+i][c+4]==b for i in range(5)):
    center=g[r+1][c+1]
    if all(g[r+i][c+j]==center for i in range(1,4) for j in range(1,4)) and center!=b:
     res.append((r,c,b,center))
 return sorted(set(res))
