import itertools, numpy as np

def predict(g):
 objs=find_objs(g)
 outx={}
 for b in [2,8]:
  ob=[o for o in objs if o[2]==b]
  # exhaustive candidate columns 0..17
  best=None
  for xs in itertools.product(range(18),repeat=len(ob)):
   good=True
   for i,a in enumerate(ob):
    for j,z in enumerate(ob):
     if i==j: continue
     if max(a[0],z[0])<=min(a[0]+4,z[0]+4):
      if a[1]<z[1] and not (xs[i]+5<=xs[j]): good=False;break
      if a[1]>z[1] and not (xs[j]+5<=xs[i]): good=False;break
      if a[1]==z[1] and a[1]<z[1] and not(xs[i]+5<=xs[j]):good=False;break
    if not good:break
   if not good: continue
   score=sum(xs) if b==8 else -sum(xs)
   if best is None or score>best[0]: best=(score,xs)
  for o,x in zip(ob,best[1]):outx[o]=x
 return {o:outx[o] for o in objs}
